def make(key):
    g = d[d.region == key].sort_values('residual', ascending=False).reset_index(drop=True); N = len(g)
    g['shown'] = g.residual.round(1)
    label, tl, note, link = SPEC[key]

    def plot(fig):
        ax = fig.add_axes([0.1, 0.0, 0.8, 0.95]); mf.style_axes(ax, bottom=False); ax.set_xticks([]); ax.set_yticks([])
        y = np.arange(N)
        ax.barh(y, g.residual, height=0.68, color=[mf.NAVY if v >= 0 else mf.RED for v in g.shown], zorder=2)
        ax.set_ylim(N - 0.5, -1.3)
        lo, hi = min(g.residual.min(), 0), max(g.residual.max(), 0); ax.set_xlim(lo * 1.02 - 0.01, hi * 1.02 + 0.01)
        mf.zero_line(ax, 'v', span=(N - 0.5, -0.6))
        off = mf.pt(14)
        for i, row in g.iterrows():
            v = row.residual; pos = row.shown >= 0; cc = mf.NAVY if pos else mf.RED
            ax.annotate(row['name'], (0, i), xytext=(-off if pos else off, 0), textcoords='offset points', ha='right' if pos else 'left',
                        va='center', fontsize=mf.pt(mf.T_LABEL), family=mf.CALIBRI, color=mf.LABEL)
            ax.annotate(mf.fmt(row.shown) if row.shown != 0 else '0.0', (v, i), xytext=(off if v >= 0 else -off, 0), textcoords='offset points',
                        ha='left' if v >= 0 else 'right', va='center', fontsize=mf.pt(mf.T_VALUE), family=mf.CALIBRI, fontweight='bold', color=cc)
        ax.text(0, -1.0, 'What income predicts', ha='center', va='bottom', fontsize=mf.pt(mf.T_HEADER), family=mf.CALIBRI, color=mf.GREY_TXT)
        mf.fit_width(fig, ax)

    title = ' '.join(tl) if tl else TITLE[key]
    caption = ('Source: Social Progress Imperative, 2026 Global Social Progress Index; Moving Frontiers calculations.\n'
               f'Note: Predicted score from a regression of the 2025 SPI on log GDP per capita (PPP) across all {len(d)} ranked countries with '
               f'GDP data (R² = {r2:.2f}). {note}\n'
               f'Read more: {link or "movingfrontiers.substack.com/more-than-money-can-explain"}')
    stem = f'chart-spi-vs-income-{key}'
    H = 2700 + (N - 28) * 57
    size = mf.compose(plot, title, f'SPI score minus the score predicted by GDP per capita, {label}, 2025, points', caption, f'{stem}.png',
                      expl='Navy: more social progress than income predicts. Red: less.', W=2160, H=H, title_lines=tl)
    g[['code', 'name', 'gdppc_2025', 'spi_2025', 'predicted', 'residual']].round(3).to_csv(f'{stem}.csv', index=False)
    print(key, N, size)


